// Code in JavaScript (page du rapport) : v2026.11.17-5 : « Détail des jours précédents » replié dans un menu (fermé par défaut),
//   les 7 jours les plus récents d'abord, les plus anciens dans un 2e menu « Jours plus anciens » ; v2026.11.14-5 : titres des vérifications en bleu (comme DIAGNOSTIC) ; v2026.11.12-2 : détail des jours précédents
const rapport = $input.first().json;
const dateGeneration = new Date().toLocaleString('fr-CA', {
  timeZone: 'America/Toronto',
  dateStyle: 'full',
  timeStyle: 'short'
});

const STATUS_COLOR = { ok: '#3fb27f', warn: '#e3a73a', crit: '#e5534b' };
const TAG_LABEL = { ok: '[OK]', warn: '[WARN]', crit: '[CRIT]' };

function escapeHtml(str) {
  return String(str == null ? '' : str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// --- Statistiques du rapport : temps, jetons, débit (calculées dans Code in JavaScript1) ---
function duree(sec) {
  if (sec == null) return null;
  const m = Math.floor(sec / 60), s = sec % 60;
  return m ? m + ' min ' + String(s).padStart(2, '0') + ' s' : s + ' s';
}
const nb = n => Number(n || 0).toLocaleString('fr-CA');
const st = rapport.stats || null;
let statsHtml = '';
if (st) {
  const morceaux = [];
  if (st.duree_totale_s != null) morceaux.push(`<span>⏱ Rapport généré en <b>${duree(st.duree_totale_s)}</b></span>`);
  morceaux.push(`<span>🧠 Ollama : <b>${duree(st.duree_ollama_s)}</b> (${nb(st.appels_ollama)} appels)</span>`);
  morceaux.push(`<span>📥 <b>${nb(st.jetons_lus)}</b> jetons lus</span>`);
  morceaux.push(`<span>📤 <b>${nb(st.jetons_ecrits)}</b> jetons écrits</span>`);
  morceaux.push(`<span>Σ <b>${nb(st.jetons_total)}</b> jetons</span>`);
  if (st.debit_jetons_s != null) morceaux.push(`<span>⚡ <b>${Number(st.debit_jetons_s).toLocaleString('fr-CA')}</b> jetons/s</span>`);
  statsHtml = `<div class="stats">${morceaux.join('')}</div>`;
}

// --- Historique sur 30 jours : une pastille par jour et par système (le plus récent à droite) ---
const HIST_COULEUR = { ok: '#3fb27f', warn: '#e3a73a', crit: '#e5534b' };
const histo = Array.isArray(rapport.historique) ? rapport.historique : [];
let histoHtml = '';
if (histo.length) {
  const jourCourt = j => new Date(j + 'T12:00:00').toLocaleDateString('fr-CA', { day: 'numeric', month: 'short' });
  const lignes = rapport.services.map(s => {
    const cases = histo.map(h => {
      const st = h.statuts ? h.statuts[s.name] : null;
      const c = st ? (HIST_COULEUR[st] || '#888') : '#333';
      return `<span class="hcase" style="background:${c}" title="${jourCourt(h.jour)} : ${st ? String(st).toUpperCase() : 'pas de donnée'}"></span>`;
    }).join('');
    const nbProb = histo.filter(h => h.statuts && h.statuts[s.name] && h.statuts[s.name] !== 'ok').length;
    return `<div class="hligne"><span class="hnom">${escapeHtml(s.name)}</span><span class="hcases">${cases}</span><span class="hcompte" style="color:#e3a73a">${nbProb ? nbProb + ' j' : ''}</span></div>`;
  }).join('');
  const debits = histo.map(h => h.debit_jetons_s).filter(v => typeof v === 'number');
  const durees = histo.map(h => h.duree_totale_s).filter(v => typeof v === 'number');
  const moy = a => a.reduce((x, y) => x + y, 0) / a.length;
  const tendance = [];
  if (debits.length) tendance.push(`Débit Ollama : aujourd'hui <b>${debits[debits.length - 1].toLocaleString('fr-CA')}</b> jetons/s, moyenne <b>${(Math.round(moy(debits) * 10) / 10).toLocaleString('fr-CA')}</b>`);
  if (durees.length) tendance.push(`Durée du rapport : moyenne <b>${Math.round(moy(durees) / 60)} min</b>`);

  // Détail des jours précédents : pourquoi un jour était en WARN ou en CRIT (aujourd'hui est déjà dans « À surveiller »)
  // Le détail n'existe que pour les jours enregistrés avec Code in JavaScript1 v2026.11.12-2 ou plus récent.
  const jourLong = j => new Date(j + 'T12:00:00').toLocaleDateString('fr-CA', { weekday: 'short', day: 'numeric', month: 'short' });
  const passes = histo.slice(0, -1).filter(h => h.problemes && Object.keys(h.problemes).length).reverse();
  const problemeHtml = (nom, p) => {
    const c = HIST_COULEUR[p.status] || '#888';
    const causes = (p.causes || []).filter(Boolean);
    const verifs = (p.verifications || []).filter(v => v && (v.etape || v.commande));
    const corr = p.correction || {};
    return `
      <div class="hprob" style="border-left:3px solid ${c};">
        <div class="hprob-tete"><strong>${escapeHtml(nom)}</strong> <span class="pill" style="background:${c};">${escapeHtml(String(p.status).toUpperCase())}</span>${p.heure ? ` <span class="hheure">vu à ${escapeHtml(p.heure)}</span>` : ''}</div>
        ${p.detail ? `<div>${escapeHtml(p.detail)}</div>` : ''}
        ${causes.length ? `<div class="label">Causes possibles</div><ul>${causes.map(x => `<li>${escapeHtml(x)}</li>`).join('')}</ul>` : ''}
        ${verifs.length ? `<div class="label">Vérifications proposées</div><ul>${verifs.map(v => `<li>${escapeHtml(v.etape)}${v.ou ? ` — ${escapeHtml(v.ou)}` : ''}${v.commande ? `<pre class="cmd">${escapeHtml(v.commande)}</pre>` : ''}</li>`).join('')}</ul>` : ''}
        ${p.suggestion ? `<div class="label">Solution proposée</div><div>${escapeHtml(p.suggestion)}</div>` : ''}
        ${corr.description || corr.commande ? `<div>${escapeHtml(corr.description)}</div>${corr.commande ? `<pre class="cmd">${escapeHtml(corr.commande)}</pre>` : ''}` : ''}
      </div>`;
  };
  const JOURS_VISIBLES = 7;   // jours affichés directement dans le menu ; les autres vont dans « Jours plus anciens »
  const jourHtml = h => {
    const liste = Object.entries(h.problemes).sort((a, b) => (a[1].status === 'crit' ? 0 : 1) - (b[1].status === 'crit' ? 0 : 1));
    return `
    <details class="hjour">
      <summary>${escapeHtml(jourLong(h.jour))} : ${liste.length} problème(s) — ${escapeHtml(liste.map(([n]) => n).join(', '))}</summary>
      ${liste.map(([n, p]) => problemeHtml(n, p)).join('')}
    </details>`;
  };
  const recents = passes.slice(0, JOURS_VISIBLES).map(jourHtml).join('');
  const anciens = passes.slice(JOURS_VISIBLES);
  const anciensHtml = anciens.length ? `
      <details class="hplus">
        <summary>Jours plus anciens : ${anciens.length} jour(s), du ${escapeHtml(jourLong(anciens[anciens.length - 1].jour))} au ${escapeHtml(jourLong(anciens[0].jour))}</summary>
        ${anciens.map(jourHtml).join('')}
      </details>` : '';
  const detailJoursHtml = passes.length ? `
    <details class="hdetails">
      <summary>Détail des jours précédents : ${passes.length} jour(s) avec un problème</summary>
      ${recents}${anciensHtml}
    </details>` : `
    <div class="hdetails">
      <div class="hlegende">Détail des jours précédents : aucun problème enregistré pour l'instant (conservé à partir du 12 nov. 2026, seulement pour les jours avec un problème).</div>
    </div>`;
  histoHtml = `
  <details class="histo" open>
    <summary>Historique : ${histo.length} jour(s), du ${jourCourt(histo[0].jour)} au ${jourCourt(histo[histo.length - 1].jour)}</summary>
    ${lignes}
    <div class="hlegende"><span class="hcase" style="background:#3fb27f"></span> OK &nbsp; <span class="hcase" style="background:#e3a73a"></span> WARN &nbsp; <span class="hcase" style="background:#e5534b"></span> CRIT &nbsp; <span class="hcase" style="background:#333"></span> pas de donnée &nbsp;·&nbsp; à droite : nombre de jours avec un problème</div>
    ${tendance.length ? `<div class="hlegende">${tendance.join(' &nbsp;·&nbsp; ')}</div>` : ''}
    ${detailJoursHtml}
  </details>`;
}

// --- Rangée du haut : coup d'œil rapide, juste nom + pastille ---
const glanceHtml = rapport.services.map(s => `
    <div style="display:flex; align-items:center; gap:6px; background:#222; border-radius:20px; padding:6px 14px; font-size:0.95em;">
      <span style="width:8px; height:8px; border-radius:50%; background:${STATUS_COLOR[s.status] || '#888'}; flex-shrink:0;"></span>
      ${escapeHtml(s.name)}
    </div>`).join('');

// --- Bloc DIAGNOSTIC : ce qui se passe + vérifications ---
function diagnosticBlock(s) {
  const causes = (s.causes || []).filter(Boolean);
  const verifs = (s.verifications || []).filter(v => v && (v.etape || v.commande));
  let h = `<div class="block-title">Diagnostic</div>`;

  h += `<p class="text">${escapeHtml(s.detail)}</p>`;

  if (causes.length) {
    h += `<div class="label">Causes possibles</div>
      <ul>${causes.map(c => `<li>${escapeHtml(c)}</li>`).join('')}</ul>`;
  }

  if (verifs.length) {
    h += `<div class="label">Vérifications à faire (elles ne modifient rien)</div>` + verifs.map((v, i) => `
      <div class="step">
        <div><strong class="etape">${i + 1}. ${escapeHtml(v.etape)}</strong>${v.ou ? ` — ${escapeHtml(v.ou)}` : ''}</div>
        ${v.commande ? `<pre class="cmd">${escapeHtml(v.commande)}</pre>` : ''}
        ${v.normal ? `<div class="note">Résultat normal : ${escapeHtml(v.normal)}</div>` : ''}
        ${v.sinon ? `<div class="note">Si différent : ${escapeHtml(v.sinon)}</div>` : ''}
      </div>`).join('');
  }

  if (s.a_rapporter) {
    h += `<div class="label">À me rapporter pour continuer</div><p class="text">${escapeHtml(s.a_rapporter)}</p>`;
  }
  return `<div class="block diag">${h}</div>`;
}

// --- Bloc SOLUTION : action recommandée + correction ---
function solutionBlock(s) {
  const corr = s.correction || {};
  const hasCorr = corr.description || corr.commande;
  if (!s.suggestion && !hasCorr) return '';
  let h = `<div class="block-title">Solution</div>`;

  if (s.suggestion) {
    h += `<p class="text">${escapeHtml(s.suggestion)}</p>`;
  }

  if (hasCorr) {
    h += `<div class="label">Action corrective (modifie quelque chose)</div>
      <div class="step">
        ${corr.description ? `<div>${escapeHtml(corr.description)}</div>` : ''}
        ${corr.commande ? `<pre class="cmd">${escapeHtml(corr.commande)}</pre>` : ''}
        ${corr.risque ? `<div class="note">Risque : ${escapeHtml(corr.risque)}</div>` : ''}
      </div>`;
  }
  return `<div class="block sol">${h}</div>`;
}

// --- Services qui demandent attention (warn/crit seulement) ---
const attention = rapport.services.filter(s => s.status !== 'ok');
const attentionHtml = attention.length === 0
  ? `<p style="color:#3fb27f;">✓ Aucune action requise aujourd'hui.</p>`
  : attention.map(s => `
    <div class="card" style="border-left: 4px solid ${STATUS_COLOR[s.status]};">
      <div class="card-head">
        <strong>${escapeHtml(s.name)}</strong>
        <span class="pill" style="background:${STATUS_COLOR[s.status]};">${escapeHtml(String(s.status).toUpperCase())}</span>
      </div>
      ${diagnosticBlock(s)}
      ${solutionBlock(s)}
    </div>`).join('');

const logHtml = rapport.log.map(l => `
    <div style="font-family: monospace; font-size: 0.95em; padding: 4px 0; color:#ddd;">
      ${escapeHtml(l.time)} <span style="color:${STATUS_COLOR[l.level] || '#888'}">${TAG_LABEL[l.level] || '[?]'}</span> ${escapeHtml(l.message)}
    </div>`).join('');

const html = `<!DOCTYPE html>
<html lang="fr">
<head>
  <meta charset="UTF-8">
  <title>Rapport du matin</title>
  <style>
    body {
      font-family: -apple-system, sans-serif;
      max-width: 800px;
      margin: 40px auto;
      padding: 20px;
      background: #1a1a1a;
      color: #e0e0e0;
      line-height: 1.7;
    }
    h1 { color: #4fc3f7; border-bottom: 2px solid #4fc3f7; padding-bottom: 10px; }
    .date { color: #bbb; margin-bottom: 20px; }
    .stats { display:flex; flex-wrap:wrap; gap:8px 22px; background:#222; border-radius:6px; padding:10px 14px; margin: -8px 0 22px 0; color:#e0e0e0; }
    .stats b { color:#4fc3f7; }
    .histo { background:#222; border-radius:6px; padding:10px 14px; margin: 18px 0 26px 0; clear:both; }
    .histo summary { margin-top:0; font-weight:bold; }
    .hligne { display:flex; align-items:center; gap:10px; margin:3px 0; }
    .hnom { width:230px; flex-shrink:0; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
    .hcases { display:flex; gap:2px; flex-wrap:nowrap; }
    .hcase { display:inline-block; width:12px; height:16px; border-radius:2px; }
    .hcompte { font-weight:bold; min-width:34px; }
    .hlegende { margin-top:8px; display:flex; align-items:center; gap:4px; flex-wrap:wrap; }
    .hlegende b { color:#4fc3f7; }
    .hdetails { margin-top:16px; }
    .hjour { margin:6px 0; }
    .hjour summary { margin-top:0; }
    .hdetails > summary { font-weight:bold; }
    .hdetails > details, .hplus > details { margin-left:14px; }
    .hplus { margin-top:10px; }
    .hprob { background:#1d1d1d; border-radius:6px; padding:10px 14px; margin:8px 0 12px 0; }
    .hprob-tete { display:flex; align-items:center; gap:10px; margin-bottom:6px; }
    .hheure { color:#e0e0e0; font-size:0.9em; }
    .glance { display:flex; flex-wrap:wrap; gap:8px; margin-bottom: 30px; }
    h2 { font-size: 1.1em; color: #ddd; margin-top: 30px; }
    summary { cursor: pointer; color: #ddd; margin-top: 20px; }

    .card { background: #222; padding: 18px 20px; margin-bottom: 28px; border-radius: 6px; }
    .card-head { display: flex; align-items: center; gap: 12px; font-size: 1.15em; margin-bottom: 16px; }
    .pill { color: #111; font-weight: bold; font-size: 0.8em; padding: 2px 10px; border-radius: 12px; }

    .block { padding: 16px 18px; border-radius: 6px; margin-top: 18px; }
    .block.diag { background: #2a2a2a; border-top: 3px solid #4fc3f7; }
    .block.sol  { background: #1f2d26; border-top: 3px solid #3fb27f; }
    .block-title { font-size: 1.1em; font-weight: bold; letter-spacing: 0.5px; text-transform: uppercase; margin-bottom: 10px; }
    .diag .block-title { color: #4fc3f7; }
    .sol  .block-title { color: #3fb27f; }

    .text { margin: 8px 0 14px 0; }
    .label { color: #f0f0f0; font-weight: bold; margin: 18px 0 8px 0; }
    .step { margin: 10px 0 18px 0; }
    /* Titres des vérifications en bleu, comme DIAGNOSTIC (plus précis que le thème du Journal, qui met le gras en blanc) */
    .step strong.etape { color: #4fc3f7; }
    .note { margin-top: 6px; color: #e0e0e0; }
    ul { margin: 6px 0 6px 22px; padding: 0; }
    li { margin-bottom: 6px; }
    pre.cmd {
      background: #111;
      color: #f0f0f0;
      padding: 12px 14px;
      border-radius: 6px;
      font-family: monospace;
      font-size: 1em;
      white-space: pre-wrap;
      word-break: break-all;
      user-select: all;
      margin: 10px 0;
    }
  </style>
</head>
<body>
  <h1>🌅 Rapport du matin - Homelab</h1>
  <div class="date">Généré le ${dateGeneration}</div>
  ${statsHtml}

  <div class="glance">${glanceHtml}</div>
  ${histoHtml}

  <h2>À surveiller</h2>
  ${attentionHtml}

  <details>
    <summary>Journal technique complet</summary>
    ${logHtml}
  </details>
</body>
</html>`;

return [{ json: { html_content: html } }];

// Code in JavaScript1 : v2026.11.12-2 : historique : garde aussi le détail des problèmes de chaque jour (consultable dans le rapport)
const noms = $('Préparer systèmes').all();
const heure = () => new Date().toLocaleTimeString('en-GB', { hour12: false, timeZone: 'America/Toronto' });
const asArray = v => Array.isArray(v) ? v : [];
const asText = v => (typeof v === 'string' ? v : '');

const services = $input.all().map((it, i) => {
  const name = noms[i].json.name;
  let r;
  try {
    r = JSON.parse(it.json.message.content);
  } catch (e) {
    r = { status: 'warn', detail: 'Réponse du modèle illisible', suggestion: 'Relancer la vérification' };
  }
  const corr = (r.correction && typeof r.correction === 'object') ? r.correction : {};
  return {
    name,
    status: noms[i].json.statut || r.status,
    detail: r.detail,
    suggestion: r.suggestion,
    causes: asArray(r.causes),
    verifications: asArray(r.verifications),
    correction: {
      description: asText(corr.description),
      commande: asText(corr.commande),
      risque: asText(corr.risque)
    },
    a_rapporter: asText(r.a_rapporter)
  };
});

// ---- Statistiques du rapport (temps, jetons, débit) ----
// Ollama renvoie pour chaque appel : prompt_eval_count (jetons lus), eval_count (jetons écrits),
// eval_duration et total_duration (en nanosecondes).
let lus = 0, ecrits = 0, nsEcriture = 0, nsOllama = 0;
for (const it of $input.all()) {
  const j = it.json || {};
  lus += Number(j.prompt_eval_count) || 0;
  ecrits += Number(j.eval_count) || 0;
  nsEcriture += Number(j.eval_duration) || 0;
  nsOllama += Number(j.total_duration) || 0;
}

// Heure de départ du workflow : lue dans le premier nœud (Schedule Trigger ou Webhook)
function debutWorkflow() {
  for (const nom of ['Schedule Trigger', 'Webhook']) {
    try {
      const j = $(nom).first().json;
      const t = Date.parse(j.timestamp || '');
      if (!isNaN(t)) return t;
      if (nom === 'Webhook') return null;
    } catch (e) {}
  }
  return null;
}
const debut = debutWorkflow();

const stats = {
  appels_ollama: $input.all().length,
  duree_totale_s: debut ? Math.round((Date.now() - debut) / 1000) : null,
  duree_ollama_s: Math.round(nsOllama / 1e9),
  jetons_lus: lus,
  jetons_ecrits: ecrits,
  jetons_total: lus + ecrits,
  debit_jetons_s: nsEcriture > 0 ? Math.round((ecrits / (nsEcriture / 1e9)) * 10) / 10 : null
};

// ---- Historique sur 30 jours (mémoire du workflow) ----
// Une entrée par jour. Pour chaque système, on garde le PIRE statut vu dans la journée
// (crit > warn > ok) : un rapport plus tard dans la journée n'efface plus un problème vu le matin.
// On garde aussi le détail de chaque problème (diagnostic, solution) tel qu'il était à son pire moment,
// pour pouvoir relire plus tard pourquoi un jour était en WARN ou en CRIT.
// Les statistiques (durée, jetons, débit) sont celles du dernier rapport de la journée.
// La mémoire n'est enregistrée que lors des exécutions automatiques (horaire de 4 h ou bouton du Journal),
// pas avec « Execute workflow » dans l'éditeur.
const JOURS_HISTORIQUE = 30;
const RANG = { ok: 0, warn: 1, crit: 2 };
const rang = s => (RANG[s] !== undefined ? RANG[s] : 0);
const pire = (a, b) => (rang(b) > rang(a) ? b : a);
const coupe = (s, n) => { s = asText(s); return s.length > n ? s.slice(0, n) + '…' : s; };

// Version courte d'un problème, pour limiter la taille de la mémoire du workflow
function resume(s) {
  return {
    status: s.status,
    detail: coupe(s.detail, 600),
    suggestion: coupe(s.suggestion, 400),
    causes: s.causes.slice(0, 4).map(c => coupe(c, 250)),
    verifications: s.verifications.slice(0, 3).map(v => ({
      etape: coupe(v && v.etape, 250), ou: coupe(v && v.ou, 150), commande: coupe(v && v.commande, 250)
    })),
    correction: { description: coupe(s.correction.description, 300), commande: coupe(s.correction.commande, 300) },
    heure: heure().slice(0, 5)
  };
}

const memoire = $getWorkflowStaticData('global');
const aujourdhui = new Date().toLocaleDateString('sv-SE', { timeZone: 'America/Toronto' });   // AAAA-MM-JJ
let historique = Array.isArray(memoire.historique) ? memoire.historique : [];

const ancien = historique.find(h => h.jour === aujourdhui) || {};
const anciensStatuts = (ancien.statuts && typeof ancien.statuts === 'object') ? ancien.statuts : {};
const anciensProblemes = (ancien.problemes && typeof ancien.problemes === 'object') ? ancien.problemes : {};

const statutsJour = Object.assign({}, anciensStatuts);
const problemesJour = Object.assign({}, anciensProblemes);
for (const s of services) {
  const st = s.status || 'ok';
  const avant = anciensStatuts[s.name];
  statutsJour[s.name] = avant ? pire(st, avant) : st;
  // Le détail suit le pire statut : remplacé seulement si ce rapport est au moins aussi grave que le précédent
  if (st !== 'ok' && rang(st) >= rang(avant || 'ok')) problemesJour[s.name] = resume(s);
}

historique = historique.filter(h => h.jour !== aujourdhui);
historique.push({
  jour: aujourdhui,
  statuts: statutsJour,
  problemes: problemesJour,
  duree_totale_s: stats.duree_totale_s,
  jetons_total: stats.jetons_total,
  debit_jetons_s: stats.debit_jetons_s
});
historique.sort((a, b) => a.jour.localeCompare(b.jour));
historique = historique.slice(-JOURS_HISTORIQUE);
memoire.historique = historique;

const log = services.map(s => ({ time: heure(), level: s.status, message: s.name + ' — ' + s.detail }));
return [{ json: { timestamp: new Date().toISOString(), services, log, stats, historique } }];

// Préparer systèmes : v2026.11.17-7 : fiche Kuma « NordVPN (tunnel) » (passerelle NORDVPN1_VPNV4 lue dans pfSense)
//   à la place de « NordVPN Server » (ping du serveur par ISP Modem, ne voyait pas un tunnel coupé) ; v2026.11.16-4 : Uptime Kuma : fiche de chaque moniteur important (distant ou de la maison) et pannes des 24 h lues dans le journal des pannes
// v2026.11.14-6 : nouvelle ligne « Ollama Mises à jour » (nœud check_ollama_updates)
function lire(nom) {
  try {
    const items = $(nom).all();
    if (!items.length) return null;
    return items.length === 1 ? items[0].json : { elements: items.map(i => i.json) };
  } catch (e) {
    return null;
  }
