// Le service n8n-version tourne dans un conteneur en UTC : son heure sans fuseau est en UTC.
// heureLocale() ramène tout à l'heure de Montréal ; ageDonnees() donne l'âge en heures.
function heureLocale(checked, naifEstUtc) {
  const s = String(checked || '');
  if (naifEstUtc && s.length >= 19 && !/(Z|[+-]\d\d:?\d\d)$/.test(s)) {
    const d = new Date(s.slice(0, 19) + 'Z');
    if (!isNaN(d.getTime())) {
      return d.toLocaleString('sv-SE', { timeZone: 'America/Toronto' }).replace(' ', 'T');
    }
  }
