}
function ageDonnees(checked) {
  try {
    const local = new Date().toLocaleString('sv-SE', { timeZone: 'America/Toronto' }).replace(' ', 'T');
    const a = Date.parse(local.slice(0, 19) + 'Z');
    const b = Date.parse(String(checked).slice(0, 19) + 'Z');
    if (isNaN(a) || isNaN(b)) return null;
    return (a - b) / 3600000;
  } catch (e) {
    return null;
  }
}

function nouveau() {
  const e = { statut: 'ok', raisons: [] };
  e.signaler = function (niveau, texte) {
    e.raisons.push(texte);
    if (niveau === 'crit') e.statut = 'crit';
    else if (e.statut !== 'crit') e.statut = 'warn';
  };
  return e;
}

function glances(j) {
  const e = nouveau();
  const r = {};
  if (j.cpu) {
    r.cpu_pct = arrondi(j.cpu.total);
    if (j.cpu.total >= 90) e.signaler('warn', 'Processeur à ' + arrondi(j.cpu.total) + ' %');
    if (j.cpu.iowait !== undefined) r.iowait_pct = arrondi(j.cpu.iowait);
  }
  if (j.mem) {
    r.ram_pct = arrondi(j.mem.percent);
    if (j.mem.percent >= 90) e.signaler('warn', 'Mémoire à ' + arrondi(j.mem.percent) + ' %');
  }
  if (j.memswap) r.swap_pct = arrondi(j.memswap.percent);
  if (j.load) r.charge = { min1: arrondi(j.load.min1), min5: arrondi(j.load.min5), coeurs: j.load.cpucore };
  if (Array.isArray(j.fs)) {
    const tries = j.fs.filter(d => typeof d.percent === 'number').sort((a, b) => b.percent - a.percent);
    r.nombre_de_disques = tries.length;
    r.disques_les_plus_remplis = tries.slice(0, 3).map(d => ({ montage: d.mnt_point, occupation_pct: arrondi(d.percent) }));
    const pire = tries[0];
    if (pire && pire.percent >= 90) e.signaler('crit', 'Disque ' + pire.mnt_point + ' à ' + arrondi(pire.percent) + ' %');
    else if (pire && pire.percent >= 80) e.signaler('warn', 'Disque ' + pire.mnt_point + ' à ' + arrondi(pire.percent) + ' %');
  }
  if (j.uptime) r.uptime = j.uptime;
  if (Array.isArray(j.containers)) {
    r.conteneurs = j.containers.map(c => ({ nom: c.name, etat: c.status }));
    const arretes = j.containers.filter(c => /exited|dead|unhealthy|restarting|paused|created|removing/i.test(String(c.status)));
    if (arretes.length) e.signaler('warn', arretes.length + ' conteneur(s) arrêté(s) ou en échec : ' + arretes.map(c => c.name).join(', '));
  }
  if (Array.isArray(j.alert)) {
    const recentes = j.alert.filter(a => a.end < 0 || (maintenant - a.end) < 86400);
    const heureLoc = t => new Date(t * 1000).toLocaleString('sv-SE', { timeZone: 'America/Toronto' }).slice(11, 16);
    const duree = a => (a.end > 0 && a.begin ? Math.round((a.end - a.begin) / 60) : null);
    r.alertes_24h = recentes.map(a => ({ type: a.type, etat: a.state, debut: a.begin ? heureLoc(a.begin) : null, duree_minutes: duree(a), en_cours: a.end < 0, maximum: arrondi(a.max), moyenne: arrondi(a.avg) }));
    const graves = recentes.filter(a => String(a.state).toUpperCase() === 'CRITICAL' && (a.end < 0 || (duree(a) !== null && duree(a) > ALERTE_CRITIQUE_MIN_MINUTES)));
    if (graves.length) {
      e.signaler('warn', graves.length + ' alerte(s) critique(s) longue(s) ou en cours dans les dernières 24 h : ' + graves.map(a => a.type + (a.end < 0 ? ' en cours' : ' pendant ' + duree(a) + ' min')).join(', '));
    }
  }
  const data = Object.keys(r).length ? r : { brut: court(j, 3000) };
  return { data, statut: e.statut, raisons: e.raisons };
}

function pfsense(j) {
  const e = nouveau();
  const d = j.data || {};
  if (j.status !== 'ok') e.signaler('crit', "L'API pfSense ne répond pas normalement");
  if (d.temp_c >= 75) e.signaler('warn', 'Température à ' + d.temp_c + ' °C');
  if (d.cpu_usage >= 90) e.signaler('warn', 'Processeur à ' + d.cpu_usage + ' %');
  if (d.mem_usage >= 90) e.signaler('warn', 'Mémoire à ' + d.mem_usage + ' %');
  if (d.disk_usage >= 90) e.signaler('crit', 'Disque à ' + d.disk_usage + ' %');
  else if (d.disk_usage >= 80) e.signaler('warn', 'Disque à ' + d.disk_usage + ' %');
  const data = { api_status: j.status, uptime: d.uptime, temperature_c: d.temp_c, cpu_pct: d.cpu_usage, charge: d.cpu_load_avg, ram_pct: d.mem_usage, swap_pct: d.swap_usage, disque_pct: d.disk_usage };

  // Snort : un service par interface (LAN, VLAN10, VLAN20)
  const sv = lire('check_pfsense_services');
  if (sv === null) {
    e.signaler('warn', "Vérification de Snort impossible : le nœud check_pfsense_services est absent ou n'est pas relié dans le workflow");
    data.snort = 'non vérifié';
  } else if (sv.error || !Array.isArray(sv.data)) {
    e.signaler('warn', 'Vérification de Snort impossible : ' + court(sv.error || 'réponse inattendue', 150));
    data.snort = 'non vérifié';
  } else {
    const marche = s => s.status === true || /^(running|started|active|up)$/i.test(String(s.status));
    const liste = sv.data.filter(s => /snort/i.test(String(s.name || '') + ' ' + String(s.description || '')));
    const arretes = liste.filter(s => s.enabled !== false && !marche(s));
    if (!liste.length) e.signaler('warn', 'Aucun service Snort trouvé dans la liste des services pfSense');
    else if (arretes.length) e.signaler('crit', 'Snort arrêté sur ' + arretes.length + ' interface(s) sur ' + liste.length + ' : ' + arretes.map(s => s.description || s.name).join(', '));
    data.snort = { services: liste.length, arretes: arretes.map(s => s.description || s.name) };
  }
  return { data, statut: e.statut, raisons: e.raisons };
}

