// Journal des pannes (workflow n8n « Journal des pannes ») : heures exactes des pannes des 24 dernières heures
let JOURNAL_PANNES = null;
try {
  JOURNAL_PANNES = await this.helpers.httpRequest({ method: 'GET', url: 'http://127.0.0.1:5678/webhook/journal-pannes', json: true, timeout: 15000 });
