const heureMontreal = (iso) => (iso ? new Date(iso).toLocaleString('sv-SE', { timeZone: 'America/Toronto' }).slice(0, 16) : null);

function kuma(j) {
  const e = nouveau();
  const liste = Array.isArray(j.monitors) ? j.monitors : [];
  const bas = liste.filter(m => m.status !== 'up');
  const faibles = liste.filter(m => m.status === 'up' && typeof m.uptime24h === 'number' && m.uptime24h < 99);
  const etiquette = (m) => { const f = ficheKuma(m.name); return m.name + (f && f.distant ? (f.etiquette || ' (distant, hors de la maison)') : ''); };
  if (bas.length) e.signaler('crit', bas.length + ' moniteur(s) hors ligne : ' + bas.map(etiquette).join(', '));
  if (faibles.length) e.signaler('warn', faibles.map(m => etiquette(m) + ' à ' + m.uptime24h + ' % de disponibilité sur 24 h').join('; '));
  const pire = liste.reduce((min, m) => (typeof m.uptime24h === 'number' && m.uptime24h < min ? m.uptime24h : min), 100);

  // Fiche de chaque moniteur en panne ou faible
  const decrire = (m) => {
    const f = ficheKuma(m.name);
    const o = { nom: m.name, distant: f ? f.distant : null, description: f ? f.description : null };
    if (typeof m.uptime24h === 'number') o.disponibilite_24h_pct = m.uptime24h;
    if (m.msg) o.message_kuma = court(m.msg, 200);
    return o;
  };

  // Pannes des 24 dernières heures, en heure de Montréal (seule source permise pour les heures)
  let pannes = null;
  if (JOURNAL_PANNES && Array.isArray(JOURNAL_PANNES.pannes)) {
    const limite = Date.now() - 24 * 3600 * 1000;
    pannes = JOURNAL_PANNES.pannes
      .filter(p => new Date(p.fin || Date.now()).getTime() >= limite)
      .slice(0, 6)
      .map(p => ({
        debut: heureMontreal(p.debut),
        fin: p.fin ? heureMontreal(p.fin) : null,
        terminee: !!p.fin,
        duree_min: p.duree_min,
        cause_probable: p.cause ? p.cause.nom + ' : ' + p.cause.texte : null,
        ordre: (p.ordre || []).slice(0, 8).map((a, k) => (k + 1) + '. ' + a.nom + ' tombé à ' + heureMontreal(a.tombe).slice(11) +
          (a.revenu ? ', revenu à ' + heureMontreal(a.revenu).slice(11) : ', pas encore revenu'))
      }));
  }

  const data = {
    moniteurs: liste.length,
    hors_ligne: bas.map(decrire),
    disponibilite_faible: faibles.map(decrire),
    disponibilite_24h_la_plus_basse_pct: pire,
    pannes_24h: pannes,
    journal_des_pannes: pannes === null ? 'indisponible : ne donne aucune heure de panne' : 'disponible'
  };
  return { data, statut: e.statut, raisons: e.raisons };
}

