function proxmoxMaj(j) {
  const e = nouveau();
  const liste = Array.isArray(j.data) ? j.data : null;
  if (liste === null) {
    const raison = j.errors ? JSON.stringify(j.errors) : (j.message || 'réponse inattendue');
    e.signaler('warn', 'Lecture des mises à jour Proxmox impossible : ' + court(raison, 150));
    return { data: { erreur: raison }, statut: e.statut, raisons: e.raisons };
  }
  const noms = liste.map(p => p.Package);
  const importants = noms.filter(n => /^(pve-manager|proxmox-kernel|pve-kernel|qemu-server|pve-qemu-kvm|pve-firmware|pve-container|libpve)/.test(n));
  const noyau = noms.some(n => /^(proxmox-kernel|pve-kernel)/.test(n));
  if (liste.length) {
    let msg = liste.length + ' mise(s) à jour de paquets disponible(s)';
    if (importants.length) msg += ' dont : ' + importants.slice(0, 5).join(', ');
    if (noyau) msg += ' ; un redémarrage du nœud est probablement nécessaire (noyau)';
    e.signaler('warn', msg);
  }
  const data = {
    nombre: liste.length,
    paquets_importants: importants,
    redemarrage_probable: noyau,
    paquets: liste.slice(0, 25).map(p => ({ paquet: p.Package, version_actuelle: p.OldVersion, nouvelle_version: p.Version }))
  };
  return { data, statut: e.statut, raisons: e.raisons };
}

function n8nMaj(j) {
  const e = nouveau();
  if (j.ok !== true) {
    e.signaler('warn', "Lecture de la version de n8n impossible : " + court(j.error || 'réponse inattendue', 150));
    return { data: { erreur: j.error || 'réponse inattendue' }, statut: e.statut, raisons: e.raisons };
  }
  if (j.update) {
    let msg = 'Mise à jour de n8n disponible : ' + j.installed + ' vers ' + j.latest;
    if (j.major) msg += ' (mise à jour majeure : lire les notes de version avant de la faire)';
    e.signaler('warn', msg);
  }
  const verifie = heureLocale(j.checked, true);
  const age = ageDonnees(verifie);
  if (age !== null && age > 24) {
    e.signaler('warn', 'Données de version de n8n vieilles de ' + Math.round(age) + ' h (service arrêté ?)');
  }
  const data = { version_installee: j.installed, derniere_version: j.latest, mise_a_jour_majeure: !!j.major, verifie_a: verifie, age_des_donnees_en_heures: age === null ? null : Math.max(0, Math.round(age)) };
  return { data, statut: e.statut, raisons: e.raisons };
}

function immichMaj(j) {
  const e = nouveau();
  const im = j.immich;
  if (!im) return null; // la vérification d'Immich n'est pas encore active dans le script du Synology
  if (im.ok !== true) {
