    return { data: { erreur: im.error || 'réponse inattendue' }, statut: e.statut, raisons: e.raisons };
  }
  if (im.update) {
    let msg = "Mise à jour d'Immich disponible : " + im.installed + ' vers ' + im.latest;
    if (im.major) msg += ' (mise à jour majeure : lire les notes de version avant de la faire)';
    e.signaler('warn', msg);
  }
  const data = { version_installee: im.installed, derniere_version: im.latest, mise_a_jour_majeure: !!im.major, dossier_compose: im.compose_dir || 'inconnu' };
  return { data, statut: e.statut, raisons: e.raisons };
}

function plexMaj(j) {
  const e = nouveau();
  const px = j.plex;
  if (!px) return null; // la vérification de Plex n'est pas encore active dans le script du Synology
  if (px.ok !== true) {
