// =====================================================================
// SAUVEGARDES et DISQUES : deux lignes qui regroupent plusieurs sources
// Sources : check_proxmox1_backups, check_proxmox2_backups, check_proxmox1_disques, check_proxmox2_disques
//           (HTTP Request vers l'API Proxmox), check_truenas_sante et check_synology_sante (fichiers JSON des scripts)
// =====================================================================
const SAUVEGARDE_MAX_JOURS = 8;   // aucune sauvegarde réussie depuis plus longtemps = WARN

// Synology : nombre de jours sans sauvegarde avant le WARN, selon la fréquence de chaque tâche.
// Le nom de la tâche est comparé aux motifs dans l'ordre (le premier qui correspond gagne).
// Une tâche qui ne correspond à rien garde SAUVEGARDE_MAX_JOURS (8 jours).
// MÊME TABLEAU dans js/sante.js du site : modifier les deux ensemble.
const SEUILS_SYNOLOGY = [
  { motif: /music/i,    jours: 35 },  // 1 fois par mois
  { motif: /software/i, jours: 35 },  // 1 fois par mois
  { motif: /docker/i,   jours: 3 },   // 4 fois par semaine
  { motif: /ollama/i,   jours: 3 },   // 4 fois par semaine
  { motif: /share/i,    jours: 4 },   // 3 fois par semaine
  { motif: /dashboard|active backup|serveur de fichier/i, jours: 8 },  // Active Backup, 1 fois par semaine
  { motif: /nas/i,      jours: 3 }    // 4 fois par semaine (en dernier : « nas » est un motif court)
];
const seuilSynology = t => {
  if (typeof t.max_jours === 'number') return t.max_jours;   // si le script fournit un jour son propre seuil
  const s = SEUILS_SYNOLOGY.find(x => x.motif.test(String(t.nom || '')));
  return s ? s.jours : SAUVEGARDE_MAX_JOURS;
};
const SCRUB_MAX_JOURS = 45;       // dernier scrub ZFS plus vieux = WARN
const TEMP_DISQUE_MAX = 55;       // °C
const USURE_SSD_MAX = 80;         // % d'usure (NVMe percentage_used)
const VIE_PROXMOX_MIN = 20;       // % de vie restante (colonne Wearout de Proxmox)
// Certains SSD WD Blue SA510 / 3D (modèles WDS…2B0A, ex. WDS500G2B0A-00SM50) ont un firmware qui donne l'USURE
// dans l'attribut 230 au lieu de la VIE RESTANTE : Proxmox affiche alors 4 % de vie pour un disque usé à 4 %.
// Pour ces modèles, on inverse : vie restante = 100 - wearout.
const SSD_USURE_INVERSEE = /WDS\d+[GT]2B0A/i;
const vieRestante = d => (typeof d.wearout !== 'number') ? null : (SSD_USURE_INVERSEE.test(String(d.model || '')) ? 100 - d.wearout : d.wearout);

const jours = sec => Math.floor(sec / 86400);
const dateLoc = sec => new Date(sec * 1000).toLocaleString('sv-SE', { timeZone: 'America/Toronto' }).slice(0, 16).replace(' ', ' à ');
const echec = v => /fail|error|erreur|partial|cancel|abort|suspend|interrupt/i.test(String(v || ''));

// Âge en jours d'une date locale "AAAA-MM-JJTHH:MM:SS" (null si inconnue)
function ageJours(local) {
  const h = local ? ageDonnees(local) : null;
  return h === null ? null : Math.floor(h / 24);
}

// Lit une source ; signale si elle est absente ou en erreur. Retourne null dans ce cas.
function source(e, nom, noeud, data) {
  const j = lire(noeud);
  if (j === null) {
    e.signaler('warn', nom + " : source absente (le nœud " + noeud + " n'existe pas, n'est pas relié ou n'a rien produit)");
    data[nom] = 'source absente';
    return null;
  }
  if (j.error) {
    e.signaler('warn', nom + ' : appel en échec (' + court(j.error, 120) + ')');
    data[nom] = 'appel en échec';
    return null;
  }
  return j;
}

function sauvegardes() {
  const e = nouveau();
  const data = {};

  // Proxmox : tâches vzdump (Datacenter, Backup)
  for (const [nom, noeud] of [['Proxmox 1', 'check_proxmox1_backups'], ['Proxmox 2', 'check_proxmox2_backups']]) {
    const j = source(e, nom, noeud, data);
    if (!j) continue;
    const t = (Array.isArray(j.data) ? j.data : []).filter(x => x.type === 'vzdump' && x.status);
    if (!t.length) {
      e.signaler('warn', nom + " : aucune sauvegarde dans l'historique des tâches");
      data[nom] = 'aucune sauvegarde trouvée';
      continue;
    }
    t.sort((a, b) => b.starttime - a.starttime);
    const derniere = t[0];
    const reussie = t.find(x => x.status === 'OK');
    const age = reussie ? jours(maintenant - reussie.starttime) : null;
    if (derniere.status !== 'OK') e.signaler('warn', nom + ' : dernière sauvegarde en échec le ' + dateLoc(derniere.starttime) + (derniere.id ? ' (VM/CT ' + derniere.id + ')' : '') + ' : ' + court(derniere.status, 100));
    if (!reussie) e.signaler('warn', nom + " : aucune sauvegarde réussie dans l'historique");
    else if (age > SAUVEGARDE_MAX_JOURS) e.signaler('warn', nom + ' : aucune sauvegarde réussie depuis ' + age + ' jours');
    data[nom] = {
      derniere: dateLoc(derniere.starttime), resultat: derniere.status,
      derniere_reussie: reussie ? dateLoc(reussie.starttime) : null, jours_depuis_reussie: age,
      echecs_7_jours: t.filter(x => x.status !== 'OK' && maintenant - x.starttime < 7 * 86400).length
    };
  }

  // TrueNAS : instantanés, réplications, Cloud Sync, Rsync
  const tn = source(e, 'TrueNAS', 'check_truenas_sante', data);
  if (tn) {
    const age = ageDonnees(tn.checked);
    if (age !== null && age > 24) e.signaler('warn', 'TrueNAS : données de santé vieilles de ' + Math.round(age) + ' h (tâche cron de truenas-sante.py arrêtée ?)');
    const actives = (tn.taches || []).filter(x => x.active !== false);
    actives.forEach(x => {
      if (echec(x.etat) || x.erreur) e.signaler('warn', 'TrueNAS : ' + x.type + ' « ' + x.nom + ' » en échec' + (x.erreur ? ' : ' + court(x.erreur, 100) : ''));
      const a = ageJours(x.derniere_execution);
      if (x.type !== 'Instantané' && a !== null && a > SAUVEGARDE_MAX_JOURS) e.signaler('warn', 'TrueNAS : ' + x.type + ' « ' + x.nom + ' » pas exécutée depuis ' + a + ' jours');
    });
    data.TrueNAS = actives.map(x => ({ type: x.type, nom: x.nom, etat: x.etat, derniere: x.derniere_execution }));
  }

  // Synology : Hyper Backup
  const sy = source(e, 'Synology', 'check_synology_sante', data);
  if (sy) {
    const age = ageDonnees(sy.checked);
    if (age !== null && age > 24) e.signaler('warn', 'Synology : données de santé vieilles de ' + Math.round(age) + ' h (tâche planifiée de synology-sante.py arrêtée ?)');
    const t = sy.taches || [];
    if (!t.length && !(sy.erreurs || []).length) e.signaler('warn', 'Synology : aucune tâche Hyper Backup trouvée');
    t.forEach(x => {
      if (echec(x.resultat) || echec(x.etat)) e.signaler('warn', 'Synology : Hyper Backup « ' + x.nom + ' » en échec (' + (x.resultat || x.etat) + ')');
      const a = ageJours(x.derniere_execution);
      const max = seuilSynology(x);
      if (a !== null && a > max) e.signaler('warn', 'Synology : Hyper Backup « ' + x.nom + ' » sans sauvegarde depuis ' + a + ' jours (maximum prévu : ' + max + ' jours)');
    });
    data.Synology = t.map(x => ({ tache: x.nom, resultat: x.resultat, derniere: x.derniere_execution, max_jours: seuilSynology(x) }));
  }

  [tn, sy].forEach((j, i) => (j && j.erreurs || []).forEach(m => e.signaler('warn', (i ? 'Synology' : 'TrueNAS') + ' : lecture partielle (' + court(m, 100) + ')')));
  return { data, statut: e.statut, raisons: e.raisons };
}

function disques() {
  const e = nouveau();
  const data = {};

  // Proxmox : liste des disques avec santé SMART et Wearout
  for (const [nom, noeud] of [['Proxmox 1', 'check_proxmox1_disques'], ['Proxmox 2', 'check_proxmox2_disques']]) {
    const j = source(e, nom, noeud, data);
    if (!j) continue;
    const l = Array.isArray(j.data) ? j.data : [];
    l.forEach(d => {
      const h = String(d.health || '').toUpperCase();
      if (h && !['PASSED', 'OK', 'UNKNOWN'].includes(h)) e.signaler('crit', nom + ' : disque ' + d.devpath + ' (' + (d.model || '?') + ') SMART ' + h);
      const vie = vieRestante(d);
      if (vie !== null && vie < VIE_PROXMOX_MIN) e.signaler('warn', nom + ' : SSD ' + d.devpath + ' avec seulement ' + vie + ' % de vie restante');
    });
    data[nom] = l.map(d => ({ disque: d.devpath, modele: d.model, smart: d.health, vie_restante_pct: vieRestante(d) }));
  }

  // TrueNAS : pools ZFS et SMART
  const tn = source(e, 'TrueNAS', 'check_truenas_sante', data);
  if (tn) {
    (tn.pools || []).forEach(p => {
      if (p.etat && p.etat !== 'ONLINE') e.signaler('crit', 'TrueNAS : pool ' + p.nom + ' ' + p.etat);
      else if (p.sain === false) e.signaler('crit', 'TrueNAS : pool ' + p.nom + ' signalé non sain');
      if (p.scrub_erreurs > 0) e.signaler('warn', 'TrueNAS : le dernier scrub du pool ' + p.nom + ' a trouvé ' + p.scrub_erreurs + ' erreur(s)');
      const a = ageJours(p.scrub_fin);
      if (p.nom !== 'boot-pool' && a !== null && a > SCRUB_MAX_JOURS) e.signaler('warn', 'TrueNAS : aucun scrub du pool ' + p.nom + ' depuis ' + a + ' jours');
    });
    (tn.disques || []).forEach(d => {
      const n = 'TrueNAS : disque ' + d.disque + (d.modele ? ' (' + d.modele + ')' : '');
      if (d.smart_ok === false) e.signaler('crit', n + ' : test de santé SMART échoué');
      if (d.secteurs_realloues > 0 || d.secteurs_en_attente > 0 || d.secteurs_illisibles > 0)
        e.signaler('warn', n + ' : ' + (d.secteurs_realloues || 0) + ' secteur(s) réalloué(s), ' + (d.secteurs_en_attente || 0) + ' en attente, ' + (d.secteurs_illisibles || 0) + ' illisible(s)');
      if (d.erreurs_media > 0) e.signaler('warn', n + ' : ' + d.erreurs_media + ' erreur(s) média');
      if (d.usure_pct >= USURE_SSD_MAX) e.signaler('warn', n + ' : usure du SSD à ' + d.usure_pct + ' %');
      if (d.temperature_c >= TEMP_DISQUE_MAX) e.signaler('warn', n + ' : température ' + d.temperature_c + ' °C');
    });
    data.TrueNAS = {
      pools: (tn.pools || []).map(p => ({ pool: p.nom, etat: p.etat, dernier_scrub: p.scrub_fin, erreurs_scrub: p.scrub_erreurs })),
      disques: (tn.disques || []).map(d => ({ disque: d.disque, smart_ok: d.smart_ok, temp_c: d.temperature_c, realloues: d.secteurs_realloues, en_attente: d.secteurs_en_attente, usure_pct: d.usure_pct }))
    };
  }

  // Synology : pools, volumes et disques
  const sy = source(e, 'Synology', 'check_synology_sante', data);
  if (sy) {
    (sy.stockage || []).forEach(p => { if (!p.normal) e.signaler('crit', 'Synology : ' + p.nom + ' en état ' + p.etat); });
    (sy.disques || []).forEach(d => {
      if (!d.normal) e.signaler(/fail|crash|critical/i.test(String(d.etat) + String(d.smart)) ? 'crit' : 'warn', 'Synology : ' + d.disque + ' (' + (d.modele || '?') + ') état ' + d.etat + ', SMART ' + (d.smart || '?'));
      if (d.temperature_c >= TEMP_DISQUE_MAX) e.signaler('warn', 'Synology : ' + d.disque + ' à ' + d.temperature_c + ' °C');
    });
    data.Synology = {
      stockage: (sy.stockage || []).map(p => ({ nom: p.nom, etat: p.etat })),
      disques: (sy.disques || []).map(d => ({ disque: d.disque, etat: d.etat, smart: d.smart, temp_c: d.temperature_c }))
    };
  }
  return { data, statut: e.statut, raisons: e.raisons };
}

// =====================================================================
// ÉCHÉANCES : fichier echeances.json du site (modifié à la main), lu par le nœud check_echeances
// Mêmes règles que la carte Échéances du dashboard (js/echeances.js)
// =====================================================================
const ECHEANCE_CRIT_JOURS = 7;   // échéance à 7 jours ou moins (ou passée) = CRIT
function joursJusqua(d) {
  if (!d || !/^\d{4}-\d{2}-\d{2}/.test(String(d))) return null;
  const auj = new Date().toLocaleDateString('sv-SE', { timeZone: 'America/Toronto' });   // AAAA-MM-JJ
  return Math.round((Date.parse(String(d).slice(0, 10) + 'T00:00:00Z') - Date.parse(auj + 'T00:00:00Z')) / 86400000);
}
function echeances(j) {
  const e = nouveau();
  const liste = Array.isArray(j.echeances) ? j.echeances : null;
  const tests = Array.isArray(j.restaurations) ? j.restaurations : null;
  if (liste === null && tests === null) {
    e.signaler('warn', 'Fichier echeances.json illisible ou vide : ' + court(j.error || 'réponse inattendue', 150));
    return { data: { erreur: 'echeances.json illisible' }, statut: e.statut, raisons: e.raisons };
  }
  const data = { echeances: [], tests_de_restauration: [] };
  (liste || []).forEach(x => {
    const r = joursJusqua(x.date);
    const alerte = typeof x.alerte_jours === 'number' ? x.alerte_jours : 30;
    data.echeances.push({ nom: x.nom, type: x.type, date: x.date, jours_restants: r });
    if (r === null) return;
    const quoi = x.nom + (r < 0 ? ' expiré depuis ' + (-r) + ' jour(s)' : ' expire dans ' + r + ' jour(s)') + ' (' + x.date + ')';
    const action = x.action ? ' ; action : ' + court(x.action, 250) : '';
    if (r <= ECHEANCE_CRIT_JOURS) e.signaler('crit', quoi + action);
    else if (r <= alerte) e.signaler('warn', quoi + action);
  });
  (tests || []).forEach(t => {
    const r = joursJusqua(t.dernier_test);
    const age = r === null ? null : -r;
    const max = typeof t.max_jours === 'number' ? t.max_jours : 90;
    data.tests_de_restauration.push({ nom: t.nom, dernier_test: t.dernier_test, jours_depuis: age, maximum_jours: max });
    const comment = t.comment ? ' ; comment : ' + court(t.comment, 250) : '';
    if (age === null) e.signaler('warn', 'Test de restauration jamais fait : ' + t.nom + comment);
    else if (age > max) e.signaler('warn', 'Test de restauration ' + t.nom + ' vieux de ' + age + ' jours (maximum ' + max + ')' + comment);
  });
  return { data, statut: e.statut, raisons: e.raisons };
}

// =====================================================================
// TUNNELS ET VPN : tunnels Cloudflare (accès de l'extérieur) et passerelles pfSense (WAN et NordVPN)
// Source : nœud check_tunnels_vpn
// =====================================================================
const PERTE_MAX_PCT = 10;   // perte de paquets d'une passerelle à partir de laquelle on signale (WARN)
function tunnelsVpn(j) {
  const e = nouveau();
  if (j.tunnels_erreur) e.signaler('warn', 'Tunnels Cloudflare non vérifiés : ' + court(j.tunnels_erreur, 150));
  (j.tunnels || []).forEach(t => {
    const et = String(t.etat || '').toLowerCase();
    if (et === 'down' || et === 'inactive') e.signaler('crit', 'Tunnel Cloudflare « ' + t.nom + ' » ' + et + ' : les services publiés par ce tunnel sont injoignables de l\'extérieur');
    else if (et === 'degraded') e.signaler('warn', 'Tunnel Cloudflare « ' + t.nom + ' » dégradé (' + t.connexions + ' connexion(s) sur 4)');
    else if (et === 'healthy' && t.connexions === 0) e.signaler('warn', 'Tunnel Cloudflare « ' + t.nom + ' » sans connexion active');
  });
  if (!j.tunnels_erreur && !(j.tunnels || []).length) e.signaler('warn', 'Aucun tunnel Cloudflare trouvé dans le compte');
  if (j.passerelles_erreur) e.signaler('warn', 'Passerelles pfSense non vérifiées : ' + court(j.passerelles_erreur, 150));
  (j.passerelles || []).forEach(g => {
    const nom = g.nom + (g.vpn ? ' (VPN NordVPN)' : '');
    if (!/^(online|up|ok)$/i.test(g.etat || '')) {
      e.signaler('crit', 'Passerelle ' + nom + ' : ' + (g.etat || 'état inconnu') +
        (g.vpn ? ' ; les VLAN qui sortent par le VPN n\'ont plus Internet (killswitch)' : ' ; plus d\'accès Internet par cette passerelle'));
    } else if ((g.perte_pct || 0) >= PERTE_MAX_PCT || (g.sous_etat && !/^(none|)$/i.test(g.sous_etat))) {
      e.signaler('warn', 'Passerelle ' + nom + ' instable : ' + (g.perte_pct != null ? g.perte_pct + ' % de perte' : '') +
        (g.delai_ms != null ? ', ' + g.delai_ms + ' ms' : '') + (g.sous_etat && !/^none$/i.test(g.sous_etat) ? ' (' + g.sous_etat + ')' : ''));
    }
  });
  if (!j.passerelles_erreur && !(j.passerelles || []).some(g => g.vpn)) e.signaler('warn', 'Aucune passerelle VPN (nom contenant NORD ou VPN) trouvée dans pfSense');
  const data = {
    tunnels: (j.tunnels || []).map(t => ({ tunnel: t.nom, etat: t.etat, connexions: t.connexions, centres_cloudflare: t.centres })),
    passerelles: (j.passerelles || []).map(g => ({ passerelle: g.nom, vpn: g.vpn, etat: g.etat, perte_pct: g.perte_pct, delai_ms: g.delai_ms }))
  };
  return { data, statut: e.statut, raisons: e.raisons };
}

// =====================================================================
// CONNEXIONS REFUSÉES : échecs de connexion à pfSense (interface web, SSH, sshguard) lus dans Loki
// Source : nœud check_connexions
// =====================================================================
const ECHECS_INTERNES_MAX = 5;   // tentatives ratées d'une même adresse interne en 24 h à partir desquelles on signale
function connexions(j) {
  const e = nouveau();
  if (j.erreur) {
    e.signaler('warn', 'Échecs de connexion non vérifiés : ' + court(j.erreur, 150));
    return { data: { erreur: j.erreur }, statut: e.statut, raisons: e.raisons };
  }
  const ips = j.par_ip || [];
  const externes = ips.filter(x => x.externe);
