  const debut = fin - 24 * 3600 * 1e9;
  let res;
  try {
    res = await this.helpers.httpRequest({
      method: 'GET',
      url: LOKI + '/loki/api/v1/query_range',
      qs: { query: FL + WANBLK + SYN, start: String(debut), end: String(fin), limit: 5000, direction: 'backward' },
      json: true,
      timeout: 60000,
    });
  } catch (e) {
    const rep = e && (e.response || (e.cause && e.cause.response));
    const data = rep && (rep.data || rep.body);
    const texte = data ? (typeof data === 'string' ? data : JSON.stringify(data)) : '';
    throw new Error(String(e && e.message ? e.message : e) + (texte ? ' : ' + texte.slice(0, 260) : ''));
  }
  const body = typeof res === 'string' ? JSON.parse(res) : res;
  if (!body || body.status !== 'success') throw new Error('Loki: ' + JSON.stringify(body).slice(0, 200));
  const parPort = {};
  const portsIp = {};
  let nb = 0;
  (body.data.result || []).forEach((flux) => {
    (flux.values || []).forEach((v) => {
      const f = String(v[1]).split(',');
      const i = f.indexOf('tcp');
      if (f[8] !== '4' || i !== 16) return;
      const src = f[18], dport = f[21];
