// ---- Regroupement des adresses en réseaux (calcul exact, sans IA) ----
const toInt = (ip) => ip.split('.').reduce((a, o) => a * 256 + Number(o), 0);
const toIp = (n) => [Math.floor(n / 16777216) % 256, Math.floor(n / 65536) % 256, Math.floor(n / 256) % 256, n % 256].join('.');

const lire = (s) => {
  const m = String(s).trim().match(/^(\d{1,3}(?:\.\d{1,3}){3})(?:\/(\d{1,2}))?$/);
  if (!m) return null;
  const octets = m[1].split('.').map(Number);
  if (octets.some((o) => o > 255)) return null;
  const p = m[2] === undefined ? 32 : Number(m[2]);
  if (p < 8 || p > 32) return null;
  const taille = Math.pow(2, 32 - p);
  return { net: Math.floor(toInt(m[1]) / taille) * taille, p: p };
};
// Adresse de la maison (privée) ou d'Internet
const privee = (ip) => { const e = lire(ip); return !!e && reserve(e); };
const origineDe = (ip) => (privee(ip) ? 'appareil de la maison' : 'Internet');
const sensDe = (src, dst) => {
  const s = privee(src), d = privee(dst);
  if (!s) return 'entrante : depuis Internet vers ' + dst;
  if (!d) return 'sortante : appareil de la maison vers Internet';
  return 'interne : entre deux appareils de la maison';
};

const texte = (e) => (e.p === 32 ? toIp(e.net) : toIp(e.net) + '/' + e.p);
const tailleDe = (e) => Math.pow(2, 32 - e.p);
const couvre = (a, b) => a.p <= b.p && b.net >= a.net && b.net < a.net + tailleDe(a);
const norm = (s) => { const e = lire(s); return e ? texte(e) : String(s); };

const reserve = (e) => {
  const a = Math.floor(e.net / 16777216);
  const b = Math.floor(e.net / 65536) % 256;
  return a === 0 || a === 10 || a === 127 || a >= 224 ||
    (a === 169 && b === 254) || (a === 172 && b >= 16 && b <= 31) || (a === 192 && b === 168);
};

function consolider(actuelles, nouvelles, opt) {
  const refuses = [];
  const gardes = [];   // entrées existantes illisibles ou privées : on ne les touche jamais
  const lues = [];
  const ajouter = (s, nouvelle) => {
    const e = lire(s);
    if (!e || reserve(e)) {
      if (nouvelle) refuses.push(String(s) + (e ? ' (adresse privée ou réservée)' : ' (format illisible)'));
      else gardes.push(String(s));
      return;
    }
    lues.push(Object.assign(e, { nouvelle: nouvelle }));
  };
  actuelles.forEach((s) => ajouter(s, false));
  nouvelles.forEach((s) => ajouter(s, true));

  // 1) doublons, puis entrées déjà couvertes par un réseau plus large
  const vus = new Map();
  lues.forEach((e) => {
    const k = e.net + '/' + e.p;
    if (!vus.has(k)) vus.set(k, e);
    else if (!e.nouvelle) vus.get(k).nouvelle = false;
  });
  let liste = Array.from(vus.values());
  liste = liste.filter((e) => !liste.some((o) => o !== e && o.p < e.p && couvre(o, e)));

  // 2) plusieurs adresses seules d'un même /24 : on les remplace par le /24
  const remplacements = [];
  const proteges = (opt.reseauxProteges || []).map(lire).filter(Boolean);
  const protegee = (e) => proteges.some((o) => couvre(o, e));
  const regrouper = (pMin, pCible, seuil) => {
    const groupes = new Map();
    liste.filter((e) => e.p > pCible && e.p >= pMin && !protegee(e)).forEach((e) => {
      const cle = Math.floor(e.net / Math.pow(2, 32 - pCible));
      if (!groupes.has(cle)) groupes.set(cle, []);
      groupes.get(cle).push(e);
    });
    groupes.forEach((membres, cle) => {
      if (membres.length >= seuil) {
        const reseau = { net: cle * Math.pow(2, 32 - pCible), p: pCible, nouvelle: membres.some((m) => m.nouvelle) };
        remplacements.push({ reseau: texte(reseau), remplace: membres.map(texte).sort() });
        liste = liste.filter((e) => !membres.includes(e));
        liste.push(reseau);
      }
    });
  };
  regrouper(25, 24, opt.ipPour24);
  // 3) facultatif : plusieurs entrées d'un même /16 : on les remplace par le /16
  if (opt.reseaux24Pour16 > 0) regrouper(17, 16, opt.reseaux24Pour16);
  liste = liste.filter((e) => !liste.some((o) => o !== e && o.p < e.p && couvre(o, e)));

  const finale = liste.sort((a, b) => a.net - b.net || a.p - b.p).map(texte).concat(gardes);
  const avant = new Set(actuelles.map(norm));
  const ajoutees = finale.filter((s) => !avant.has(s) && !remplacements.some((r) => r.reseau === s));
  return { finale: finale, remplacements: remplacements, ajoutees: ajoutees, refuses: refuses };
}

// Chaque entrée existante doit rester couverte par la nouvelle liste
const toutesCouvertes = (actuelles, finale) => {
  const f = finale.map(lire).filter(Boolean);
  return actuelles.every((s) => {
    const e = lire(s);
    return !e || reserve(e) || f.some((o) => couvre(o, e));
  });
};

const pf = async (etape, method, chemin, corps) => {
  const options = {
    method: method,
    url: PFSENSE + chemin,
    headers: { 'X-API-Key': PFSENSE_KEY, Accept: 'application/json' },
    json: true,
    skipSslCertificateValidation: true,
    timeout: 60000,
  };
  if (corps !== undefined) options.body = corps;
  try {
    const res = await this.helpers.httpRequest(options);
    return typeof res === 'string' ? JSON.parse(res) : res;
  } catch (e) {
    // On indique l'étape qui échoue et la réponse de l'API pfSense (elle explique souvent le refus)
    // n8n range la réponse de pfSense à des endroits différents selon la version : on les essaie tous
    const rep = e && (e.response || (e.cause && e.cause.response));
    const cand = [rep && (rep.data || rep.body), e && e.context && e.context.data, e && e.description, e && e.cause && e.cause.body, e && e.messages];
    const data = cand.find((x) => x && (typeof x !== 'object' || Object.keys(x).length));
    const suite = data ? ' : ' + (typeof data === 'string' ? data : JSON.stringify(data)).slice(0, 400) : '';
    throw new Error(etape + ' : ' + String(e && e.message ? e.message : e) + suite);
  }
};
const trouverAlias = async (etape) => {
  const o = await pf(etape, 'GET', '/api/v2/firewall/aliases');
  const liste = Array.isArray(o && o.data) ? o.data : [];
  const alias = liste.find((a) => a.name === BLOCAGE.alias);
  if (!alias) throw new Error('alias introuvable : ' + BLOCAGE.alias + ' (alias existants : ' + liste.map((a) => a.name).join(', ') + ')');
  if (!Array.isArray(alias.address)) throw new Error("liste d'adresses illisible dans l'alias");
  return alias;
};

// pfSense exige un masque sur chaque adresse d'un alias réseau : une IP seule s'écrit x.x.x.x/32
const versPf = (a) => (/^\d{1,3}(\.\d{1,3}){3}$/.test(a) ? a + '/32' : a);

// Raison du blocage de chaque IP, écrite dans le commentaire de l'alias pfSense
const raisonsBlocage = {};

// Met à jour la liste de blocage (simulation par défaut)
async function majListeBlocage(nouvelles) {
  const r = { mode: BLOCAGE.mode, alias: BLOCAGE.alias };
  if (!PFSENSE_KEY) return Object.assign(r, { etat: 'non_configuree' });
  const alias = await trouverAlias("lecture de l'alias");
  const actuelles = alias.address;
  const c = consolider(actuelles, nouvelles, BLOCAGE);
  r.entrees_avant = actuelles.length;
  r.entrees_apres = c.finale.length;
  const avant = new Set(actuelles.map(norm));
  const apres = new Set(c.finale.map(norm));
  const change = avant.size !== apres.size || Array.from(apres).some((s) => !avant.has(s));
  if (!change) return Object.assign(r, { etat: 'inchangee' });

  r.nb_ips_ajoutees = c.ajoutees.length;
  r.ips_ajoutees = c.ajoutees.slice(0, 10).map((ip) => raisonsBlocage[ip] ? ip + ' (' + raisonsBlocage[ip] + ')' : ip);
  r.regroupements = c.remplacements.slice(0, 5).map((x) => ({ reseau: x.reseau, remplace: x.remplace.slice(0, 6), nombre: x.remplace.length }));
  if (c.finale.length > BLOCAGE.maxEntrees) {
    return Object.assign(r, { etat: 'erreur', erreur: 'liste trop longue (' + c.finale.length + ' entrées, maximum ' + BLOCAGE.maxEntrees + ')' });
  }
  if (!toutesCouvertes(actuelles, c.finale)) {
    return Object.assign(r, { etat: 'erreur', erreur: "garde-fou : une entrée existante ne serait plus couverte, rien n'est écrit" });
  }
  if (BLOCAGE.mode !== 'ecriture') return Object.assign(r, { etat: 'a_mettre_a_jour' });

  // Écriture : on garde le commentaire de chaque entrée existante
  const details = Array.isArray(alias.detail) ? alias.detail : [];
  const detailDe = new Map();
  actuelles.forEach((a, i) => detailDe.set(norm(a), String(details[i] || '')));
  const jour = new Date().toISOString().slice(0, 10);
  const nouveauxDetails = c.finale.map((a) => {
    if (detailDe.has(norm(a))) return detailDe.get(norm(a));
    if (c.remplacements.some((x) => x.reseau === a)) return 'regroupé le ' + jour;
    const ip = a.replace(/\/32$/, '');
    return 'ajouté le ' + jour + (raisonsBlocage[ip] ? ' (' + raisonsBlocage[ip] + ')' : '');
  });
  await pf("modification de l'alias (PATCH)", 'PATCH', '/api/v2/firewall/alias', { id: alias.id, address: c.finale.map(versPf), detail: nouveauxDetails });
  await pf('application des changements (apply)', 'POST', '/api/v2/firewall/apply', {});
  const verif = await trouverAlias("relecture de l'alias");
  if (verif.address.length !== c.finale.length) {
    return Object.assign(r, { etat: 'erreur', erreur: "l'alias relu contient " + verif.address.length + ' entrées au lieu de ' + c.finale.length });
  }
  return Object.assign(r, { etat: 'mise_a_jour' });
}

