// check_loki_updates : versions installées de Grafana et de Loki (CT 110) comparées aux dernières versions publiées sur GitHub
const GRAFANA = 'http://IP_PRIVEE_12:PORT_10';
const LOKI = 'http://IP_PRIVEE_12:PORT_9';
const RECENT_JOURS = 14;

const get = async (url, extra) =>
  this.helpers.httpRequest(Object.assign({ method: 'GET', url: url, timeout: 30000 }, extra || {}));

const parse = (s) => {
  const m = String(s || '').trim().replace(/^v/, '').match(/^(\d+)\.(\d+)\.(\d+)$/);
  return m ? [Number(m[1]), Number(m[2]), Number(m[3])] : null;
};
const cmp = (a, b) => a[0] - b[0] || a[1] - b[1] || a[2] - b[2];

const versionGrafana = async () => {
  const r = await get(GRAFANA + '/api/health', { json: true });
  const o = typeof r === 'string' ? JSON.parse(r) : r;
  if (!o || !o.version) throw new Error('réponse inattendue de Grafana');
  return String(o.version);
};

const versionLoki = async () => {
  try {
    const r = await get(LOKI + '/loki/api/v1/status/buildinfo', { json: true });
    const o = typeof r === 'string' ? JSON.parse(r) : r;
    if (o && o.version) return String(o.version);
  } catch (e) {
    // on essaie les métriques ci-dessous
  }
  const t = await get(LOKI + '/metrics');
  const m = String(t).match(/loki_build_info\{[^}]*version="([^"]+)"/);
  if (!m) throw new Error('version de Loki illisible');
  return m[1];
};

const publiees = async (depot) => {
  const r = await get('https://api.github.com/repos/' + depot + '/releases', {
    qs: { per_page: 100 },
    headers: { Accept: 'application/vnd.github+json', 'User-Agent': 'n8n-check-updates' },
    json: true,
  });
  const liste = typeof r === 'string' ? JSON.parse(r) : r;
  if (!Array.isArray(liste)) throw new Error('réponse inattendue de GitHub');
  return liste
    .filter((x) => !x.prerelease && !x.draft && parse(x.tag_name))
    .map((x) => ({ v: parse(x.tag_name), tag: String(x.tag_name).replace(/^v/, ''), date: x.published_at }));
};

const evaluer = async (nom, depot, lireVersion) => {
  try {
    const installee = await lireVersion();
    const ins = parse(installee);
    if (!ins) throw new Error('version installée illisible : ' + installee);
    const rel = await publiees(depot);
    const memeMajeure = rel.filter((x) => x.v[0] === ins[0] && cmp(x.v, ins) > 0).sort((a, b) => cmp(b.v, a.v));
    const majeures = rel.filter((x) => x.v[0] > ins[0]).sort((a, b) => cmp(b.v, a.v));
    const meilleure = memeMajeure[0] || null;
    const majeure = majeures[0] || null;
    const type = meilleure ? (meilleure.v[1] === ins[1] ? 'correctif' : 'mineure') : null;
    const age = meilleure ? Math.floor((Date.now() - Date.parse(meilleure.date)) / 86400000) : null;
    return {
      nom: nom,
      installee: installee,
      derniere: meilleure ? meilleure.tag : installee,
      type: type,
      publiee: meilleure ? String(meilleure.date).slice(0, 10) : null,
      recente: meilleure ? age < RECENT_JOURS : false,
      majeure: majeure ? majeure.tag : null,
    };
  } catch (e) {
    return { nom: nom, erreur: String(e && e.message ? e.message : e) };
  }
};

let donnees;
try {
