// "network" -> "Network"
const majuscule = s => String(s || '').charAt(0).toUpperCase() + String(s || '').slice(1);

// Parcourt la réponse et garde chaque objet qui a une version et un champ updateAvailable
function trouverApps(o, res) {
  if (Array.isArray(o)) { o.forEach(x => trouverApps(x, res)); return res; }
  if (o && typeof o === 'object') {
    if ('updateAvailable' in o && typeof o.version === 'string') {
      const nom = o.name || o.type || o.displayName || o.id;
      if (nom && o.isInstalled !== false && !res.some(r => r.nom.toLowerCase() === String(nom).toLowerCase())) {
        res.push({ nom: majuscule(nom), version: o.version, maj: o.updateAvailable });
      }
    }
    Object.values(o).forEach(v => trouverApps(v, res));
  }
  return res;
}

// "v6.0.17+701d2b2" -> [6, 0, 17] ; null si aucun numéro trouvé
function numeros(v) {
  const m = String(v || '').match(/(\d+)\.(\d+)\.(\d+)/);
  return m ? [Number(m[1]), Number(m[2]), Number(m[3])] : null;
}
// "v6.0.17+701d2b2" -> "6.0.17"
const versionCourte = v => { const n = numeros(v); return n ? n.join('.') : String(v || ''); };
// true si a est plus récente que b
function plusRecente(a, b) {
  for (let i = 0; i < 3; i++) { if (a[i] !== b[i]) return a[i] > b[i]; }
  return false;
}

// Cherche dans /api/system un champ de version du firmware (priorité aux clés qui contiennent "firmware", puis au chemin le plus court)
function trouverVersionFirmware(o) {
  const candidats = [];
  (function parcours(x, chemin) {
    if (Array.isArray(x)) { x.forEach((y, i) => parcours(y, chemin + '[' + i + ']')); return; }
    if (x && typeof x === 'object') {
      for (const [k, v] of Object.entries(x)) {
        const p = chemin ? chemin + '.' + k : k;
        if (typeof v === 'string' && /^v?\d+\.\d+\.\d+/.test(v) && /firmware|version/i.test(k)) candidats.push({ chemin: p, cle: k, valeur: v });
        else if (v && typeof v === 'object') parcours(v, p);
      }
    }
  })(o, '');
  candidats.sort((a, b) =>
    (Number(/firmware/i.test(b.cle)) - Number(/firmware/i.test(a.cle))) ||
    (a.chemin.split('.').length - b.chemin.split('.').length));
  return candidats[0] || null;
}

// Cherche dans la réponse du serveur Ubiquiti la première entrée de la bonne plateforme
function trouverDernierFirmware(o, plateforme) {
  if (Array.isArray(o)) { for (const x of o) { const r = trouverDernierFirmware(x, plateforme); if (r) return r; } return null; }
  if (o && typeof o === 'object') {
    if (typeof o.version === 'string' && o.platform === plateforme) return o;
    for (const v of Object.values(o)) { const r = trouverDernierFirmware(v, plateforme); if (r) return r; }
  }
  return null;
}

const produits = [];

for (const c of CONSOLES) {
  if (!c.motDePasse || c.motDePasse.startsWith('COLLER_')) continue; // console non configurée : ignorée

  // 1) Connexion
  let entetes;
  try {
    const login = await this.helpers.httpRequest({
      method: 'POST',
      url: c.url + '/api/auth/login',
      body: { username: c.utilisateur, password: c.motDePasse, rememberMe: false },
      json: true,
      skipSslCertificateValidation: true,
      returnFullResponse: true,
    });
    const cookies = [].concat(login.headers['set-cookie'] || []).map(x => x.split(';')[0]).join('; ');
    const csrf = login.headers['x-csrf-token'] || login.headers['x-updated-csrf-token'] || '';
    entetes = { Cookie: cookies, 'X-CSRF-Token': csrf, Accept: 'application/json' };
  } catch (e) {
    produits.push({ nom: c.nom + ' (connexion)', console: c.nom, installe: null, derniere: null, majDisponible: false, derniereInconnue: true,
      erreur: 'Connexion au compte local impossible : ' + String(e.message).slice(0, 120) });
    continue;
  }

  // 2) Applications et mises à jour annoncées
  try {
    const r = await this.helpers.httpRequest({
      method: 'GET',
      url: c.url + '/api/apps',
      headers: entetes,
      skipSslCertificateValidation: true,
      json: true,
    });
    const apps = trouverApps(r, []);
    if (!apps.length) {
      produits.push({ nom: c.nom + ' (applications)', console: c.nom, installe: null, derniere: null, majDisponible: false, derniereInconnue: true,
        erreur: 'Aucune application trouvée dans /api/apps : ' + JSON.stringify(r).slice(0, 150) });
    }
    for (const a of apps) {
      const nouvelle = a.maj && typeof a.maj === 'string' && a.maj !== a.version ? a.maj : null;
      produits.push({
        nom: a.nom,
        console: c.nom,
        installe: a.version,
        derniere: nouvelle || a.version,
        majDisponible: !!nouvelle,
        derniereInconnue: false,
        erreur: null,
      });
    }
  } catch (e) {
    produits.push({ nom: c.nom + ' (applications)', console: c.nom, installe: null, derniere: null, majDisponible: false, derniereInconnue: true,
      erreur: 'Lecture de /api/apps impossible : ' + String(e.message).slice(0, 120) });
  }

  // 3) Version UniFi OS installée (avec la session ouverte)
  let osInstalle = null, osSource = null, osErreur = null;
  try {
    const s = await this.helpers.httpRequest({
      method: 'GET',
      url: c.url + '/api/system',
      headers: entetes,
      skipSslCertificateValidation: true,
      json: true,
    });
    const v = trouverVersionFirmware(s);
    if (v) { osInstalle = v.valeur; osSource = '/api/system → ' + v.chemin; }
    else osErreur = 'Version UniFi OS introuvable dans /api/system. Champs reçus : ' + Object.keys(s || {}).join(', ').slice(0, 200);
  } catch (e) {
    osErreur = 'Lecture de /api/system impossible : ' + String(e.message).slice(0, 120);
  }

  // 4) Déconnexion
  try {
    await this.helpers.httpRequest({ method: 'POST', url: c.url + '/api/auth/logout', headers: entetes, skipSslCertificateValidation: true });
  } catch (e) {}

  // 5) Dernière version UniFi OS publiée par Ubiquiti (canal release)
  let osDerniere = null;
  if (!osErreur) {
    try {
      const cat = await this.helpers.httpRequest({
        method: 'GET',
        url: 'https://fw-update.ubnt.com/api/firmware?filter=eq~~product~~' + c.produitFw +
             '&filter=eq~~channel~~release&filter=eq~~platform~~' + c.plateforme + '&sort=-version&limit=1',
        json: true,
      });
      const f = trouverDernierFirmware(cat, c.plateforme);
      if (f) osDerniere = f.version;
      else osErreur = 'Aucune version ' + c.plateforme + ' trouvée sur fw-update.ubnt.com';
    } catch (e) {
      osErreur = 'Lecture de fw-update.ubnt.com impossible : ' + String(e.message).slice(0, 120);
    }
  }

  // 6) Comparaison
  const nInst = numeros(osInstalle), nDern = numeros(osDerniere);
  if (!osErreur && (!nInst || !nDern)) osErreur = 'Version illisible (installée : ' + osInstalle + ', publiée : ' + osDerniere + ')';
  const majOs = !osErreur && plusRecente(nDern, nInst);
  produits.push({
    nom: 'UniFi OS ' + c.nom,
    console: c.nom,
    installe: osInstalle ? versionCourte(osInstalle) : null,
    derniere: osDerniere ? versionCourte(osDerniere) : null,
    majDisponible: majOs,
    derniereInconnue: !!osErreur,
    erreur: osErreur,
    source: osSource,
  });
}

return [{ json: { produits } }];

// check_tunnels_vpn : v2026.11.12-6 : première version (tunnels Cloudflare + passerelles pfSense WAN et NordVPN)
// check_tunnels_vpn
// 1) Tunnels Cloudflare : état de chaque tunnel (healthy, degraded, down, inactive) et nombre de connexions,
//    lus avec un jeton API en lecture seule (permission Account, Cloudflare Tunnel, Read).
// 2) Passerelles pfSense : état, perte et délai de chaque passerelle (API REST v2 /status/gateways).
//    Les passerelles VPN sont reconnues par leur nom (NORD ou VPN).
// Sortie : 1 item { tunnels, tunnels_erreur, passerelles, passerelles_erreur }

const CLOUDFLARE = {
  compte: 'A_REMPLIR',
  jeton: 'A_REMPLIR',
};
const PFSENSE = {
  url: 'https://IP_PRIVEE_2:PORT_2',
  cle: 'A_REMPLIR',   // la même clé que dans le nœud check_pfsense_logs
};

const sortie = { tunnels: [], tunnels_erreur: null, passerelles: [], passerelles_erreur: null };

// ---- 1) Tunnels Cloudflare ----
if (CLOUDFLARE.jeton.startsWith('COLLER_')) {
  sortie.tunnels_erreur = 'jeton Cloudflare absent dans le nœud check_tunnels_vpn';
} else {
  try {
    const r = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.cloudflare.com/client/v4/accounts/' + CLOUDFLARE.compte + '/cfd_tunnel?is_deleted=false',
      headers: { Authorization: 'Bearer ' + CLOUDFLARE.jeton },
      json: true,
    });
    if (!r.success) {
      sortie.tunnels_erreur = 'réponse Cloudflare en échec : ' + JSON.stringify(r.errors || r).slice(0, 150);
    } else {
      sortie.tunnels = (r.result || []).map(t => ({
        nom: t.name,
        etat: t.status,                                   // healthy, degraded, down, inactive
        connexions: (t.connections || []).length,
        centres: [...new Set((t.connections || []).map(c => c.colo_name).filter(Boolean))],
        actif_depuis: t.conns_active_at || null,
      }));
    }
  } catch (e) {
    sortie.tunnels_erreur = 'appel Cloudflare impossible : ' + String(e.message).slice(0, 150);
  }
}

// ---- 2) Passerelles pfSense ----
const texte = v => (v == null ? '' : String(v));
const nombre = v => { const n = parseFloat(texte(v).replace(',', '.')); return isNaN(n) ? null : n; };
if (PFSENSE.cle.startsWith('COLLER_')) {
  sortie.passerelles_erreur = 'clé API pfSense absente dans le nœud check_tunnels_vpn';
} else {
  try {
    const r = await this.helpers.httpRequest({
      method: 'GET',
      url: PFSENSE.url + '/api/v2/status/gateways',
      headers: { 'X-API-Key': PFSENSE.cle, Accept: 'application/json' },
      skipSslCertificateValidation: true,
      json: true,
    });
    const liste = Array.isArray(r.data) ? r.data : [];
    if (!liste.length) sortie.passerelles_erreur = 'aucune passerelle dans la réponse : ' + JSON.stringify(r).slice(0, 150);
    sortie.passerelles = liste.map(g => {
      const nom = texte(g.name || g.gateway || g.monitorip);
      return {
        nom,
        vpn: /nord|vpn/i.test(nom),
        etat: texte(g.status),                            // online, down...
        sous_etat: texte(g.substatus),                    // none, highloss, highdelay...
        perte_pct: nombre(g.loss),
        delai_ms: nombre(g.delay),
        ip_surveillee: texte(g.monitorip),
      };
    });
  } catch (e) {
    sortie.passerelles_erreur = 'appel pfSense impossible : ' + String(e.message).slice(0, 150);
  }
}

return [{ json: sortie }];

// check_connexions : v2026.11.12-6 : première version (échecs de connexion à pfSense lus dans Loki)
// check_connexions
// Lit dans Loki (CT 110, IP_PRIVEE_12:PORT_9) les 24 dernières heures des journaux pfSense qui parlent
// d'échecs de connexion :
//  - interface web pfSense : « webConfigurator authentication error for user 'x' from: IP » (app php-fpm ou php)
//  - SSH de pfSense : « Failed password », « Invalid user » (app sshd)
//  - sshguard : « Attack from "IP" ... », « Blocking "IP" ... » (app sshguard)
// Regroupe par adresse IP et par compte. Sortie : 1 item { total, par_type, par_ip, comptes, exemples, erreur }

const LOKI = 'http://IP_PRIVEE_12:PORT_9';
const REQUETE = '{app=~"php-fpm|php|sshd|sshguard"} |~ "(?i)authentication error|failed password|invalid user|attack from|blocking"';
const LIMITE = 2000;

const maintenantNs = BigInt(Date.now()) * 1000000n;
const debutNs = maintenantNs - 24n * 3600n * 1000000000n;
const prive = ip => /^(10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.|127\.)/.test(ip);

const sortie = { total: 0, par_type: {}, par_ip: [], comptes: [], exemples: [], erreur: null, requete: REQUETE };

try {
  const r = await this.helpers.httpRequest({
    method: 'GET',
    url: LOKI + '/loki/api/v1/query_range',
    qs: { query: REQUETE, start: debutNs.toString(), end: maintenantNs.toString(), limit: LIMITE, direction: 'backward' },
    json: true,
  });
  const lignes = [];
  for (const s of (r.data && r.data.result) || []) {
    const app = (s.stream && s.stream.app) || '?';
    for (const [ts, msg] of s.values || []) lignes.push({ ts: Number(BigInt(ts) / 1000000n), app, msg: String(msg) });
  }
  lignes.sort((a, b) => b.ts - a.ts);

  const ips = {}, comptes = {};
  for (const l of lignes) {
    let type;
    if (/authentication error/i.test(l.msg)) type = 'interface web pfSense';
    else if (/attack from|blocking/i.test(l.msg)) type = 'sshguard';
    else type = 'SSH pfSense';
    sortie.par_type[type] = (sortie.par_type[type] || 0) + 1;
    sortie.total++;

    const ip = (l.msg.match(/(\d{1,3}(?:\.\d{1,3}){3})/) || [])[1] || 'inconnue';
    const compte = (l.msg.match(/user '([^']+)'/i) || l.msg.match(/(?:invalid user|for(?: invalid user)?) (\S+) from/i) || [])[1] || null;
    const x = ips[ip] || (ips[ip] = { ip, externe: ip !== 'inconnue' && !prive(ip), tentatives: 0, types: {}, derniere: null });
    x.tentatives++;
    x.types[type] = (x.types[type] || 0) + 1;
    if (!x.derniere) x.derniere = new Date(l.ts).toLocaleString('sv-SE', { timeZone: 'America/Toronto' }).slice(0, 16);
    if (compte) comptes[compte] = (comptes[compte] || 0) + 1;
    if (sortie.exemples.length < 5) sortie.exemples.push(l.msg.slice(0, 200));
  }
  sortie.par_ip = Object.values(ips).sort((a, b) => b.tentatives - a.tentatives).slice(0, 10)
    .map(x => ({ ...x, types: Object.entries(x.types).map(([t, n]) => t + ' : ' + n).join(', ') }));
  sortie.comptes = Object.entries(comptes).sort((a, b) => b[1] - a[1]).slice(0, 10).map(([compte, n]) => ({ compte, tentatives: n }));
  if (lignes.length >= LIMITE) sortie.note = 'limite de ' + LIMITE + ' lignes atteinte : le total est un minimum';
} catch (e) {
  sortie.erreur = 'lecture de Loki impossible : ' + String(e.message).slice(0, 150);
}

return [{ json: sortie }];

// check_ollama_updates : v2026.11.14-6 : première version
// check_ollama_updates
// Version d'Ollama installée sur le PC Ollama (IP_PRIVEE_14, /api/version) comparée à la dernière version
// stable publiée sur GitHub (ollama/ollama, releases/latest : les versions rc ne comptent pas).
// Sortie : 1 item { installee, derniere, publiee, jours_depuis_publication, type, erreur }
//   type = 'majeure' | 'mineure' | 'correctif' | null (null = à jour)

const OLLAMA = 'http://IP_PRIVEE_14:PORT_11';
const GITHUB = 'https://api.github.com/repos/ollama/ollama/releases/latest';

// "v0.41.2" ou "0.41.2" -> [0, 41, 2] ; null si illisible
function numeros(v) {
  const m = String(v || '').match(/(\d+)\.(\d+)\.(\d+)/);
  return m ? [Number(m[1]), Number(m[2]), Number(m[3])] : null;
}
const court = v => { const n = numeros(v); return n ? n.join('.') : String(v || ''); };

const sortie = { installee: null, derniere: null, publiee: null, jours_depuis_publication: null, type: null, erreur: null };

// 1) Version installée
try {
  const r = await this.helpers.httpRequest({ method: 'GET', url: OLLAMA + '/api/version', json: true, timeout: 10000 });
  sortie.installee = r && r.version ? court(r.version) : null;
  if (!sortie.installee) sortie.erreur = 'réponse inattendue de /api/version : ' + JSON.stringify(r).slice(0, 120);
} catch (e) {
  sortie.erreur = 'Ollama injoignable (' + OLLAMA + ') : ' + String(e.message).slice(0, 120);
}

// 2) Dernière version stable sur GitHub
if (!sortie.erreur) {
  try {
    const r = await this.helpers.httpRequest({
      method: 'GET', url: GITHUB, json: true, timeout: 15000,
      headers: { 'User-Agent': 'n8n-homelab', Accept: 'application/vnd.github+json' },
    });
    sortie.derniere = court(r.tag_name);
    sortie.publiee = r.published_at ? String(r.published_at).slice(0, 10) : null;
    if (sortie.publiee) {
      sortie.jours_depuis_publication = Math.floor((Date.now() - Date.parse(sortie.publiee + 'T00:00:00Z')) / 86400000);
    }
  } catch (e) {
    sortie.erreur = 'lecture de GitHub impossible : ' + String(e.message).slice(0, 120);
  }
}

// 3) Comparaison
const a = numeros(sortie.installee), b = numeros(sortie.derniere);
if (!sortie.erreur && a && b) {
  if (b[0] > a[0]) sortie.type = 'majeure';
  else if (b[0] === a[0] && b[1] > a[1]) sortie.type = 'mineure';
  else if (b[0] === a[0] && b[1] === a[1] && b[2] > a[2]) sortie.type = 'correctif';
} else if (!sortie.erreur) {
  sortie.erreur = 'version illisible (installée : ' + sortie.installee + ', publiée : ' + sortie.derniere + ')';
}

return [{ json: sortie }];
